INSERT INTO public.policy_configs VALUES
	('c5bce986-584b-49bb-ad4b-19a03260d908', 'v1', true, '{"version": "v1", "base_fit": {"bounds": {"max": 100, "min": 0}, "formula": "hard_gate_cap * (weighted_structured_score * 0.75 + semantic_score * 0.25)"}, "mvp_scope": {"batch_matching_enabled": false, "autonomous_agents_enabled": false, "deferred_acceptance_enabled": false, "centralized_clearing_enabled": false}, "confidence": {"extraction_levels": ["high", "medium", "low"], "admin_review_thresholds": {"review_taxonomy_mismatch": true, "review_conflicting_signals": true, "review_geography_ambiguity": true, "review_credential_ambiguity": true, "review_low_match_confidence": true, "review_low_extraction_confidence": true}}, "eligibility": {"eligible": {"hard_gate_cap": 1.0}, "near_fit": {"hard_gate_cap": 0.75}, "ineligible": {"hard_gate_cap": 0.35}}, "feature_flags": {"applicant_self_signup": true, "admin_override_enabled": true, "applicant_chat_enabled": true, "direct_messaging_default": false, "admin_policy_editor_enabled": true, "employer_invite_only_default": true, "employer_global_candidate_search_default": false}, "null_handling": {"defaults": {"experience_unknown": 50, "geography_fully_unknown": 35, "geography_partially_known": 50, "compensation_alignment_unknown": 70, "credentials_unknown_nonrequired": 50, "work_style_signal_alignment_unknown": 50, "employer_soft_pref_alignment_unknown": 50}, "required_credential_behavior": {"if_job_requires_credential_and_applicant_data_missing": {"auto_fail": false, "eligibility_status": "near_fit", "requires_review_if_low_confidence": true}}}, "semantic_score": {"enabled": true, "formula": "0.4*skills_overlap + 0.3*job_family_similarity + 0.2*experience_text_relevance + 0.1*intent_alignment"}, "policy_reranking": {"enabled": true, "formula": "policy_adjusted_score = clamp(base_fit_score + sum(policy_modifiers), 0, 100)", "policies": {"opportunity_upside": {"enabled": true, "modifiers": {"otherwise": 0, "meaningful_upside_and_near_fit_or_better": 2}}, "geography_preference": {"enabled": true, "modifiers": {"uncertain": 0, "infeasible": 0, "local_feasible": 6, "same_state_or_regional": 4, "travel_heavy_and_willing": 1, "relocation_required_and_willing": 1}}, "readiness_preference": {"enabled": true, "modifiers": {"near_completion": 3, "significant_wait": 0, "ready_now_or_timing_aligned": 5}}, "partner_employer_preference": {"enabled": true, "modifiers": {"non_partner": 0, "partner_employer": 5}, "constraints": {"max_override_gap": 12}}, "funded_training_pathway_alignment": {"enabled": true, "modifiers": {"unrelated": 0, "direct_alignment": 6, "adjacent_alignment": 3}}, "missing_critical_requirement_penalty": {"enabled": true, "modifiers": {"missing_mandatory_credential": -12, "missing_minor_requirements_only": -2, "missing_important_nonmandatory_skill_cluster": -6}}}}, "structured_score": {"weights": {"timing_readiness": 10, "industry_alignment": 5, "geography_alignment": 20, "credential_readiness": 15, "compensation_alignment": 5, "trade_program_alignment": 25, "work_style_signal_alignment": 5, "employer_soft_pref_alignment": 5, "experience_internship_alignment": 10}, "total_weight": 100}}', 'Default scoring and policy config — SkillPointe Match MVP (from SCORING_CONFIG.yaml v1)', NULL, NULL, NULL, NULL, '2026-03-17 23:56:06.346672+00', '2026-03-17 23:56:06.346672+00');


